/bin/bash -c "python3 - <<'PY'
from math import inf

def eta(a,b):
    if b<a: return 1-b/a
    if b>a: return 1-(1-b)/(1-a)
    return 0.0

def rowunfair(a,b,wa,wb):
    return min(wa*eta(v,a)+wb*eta(v,b) for v in (0.0,1.0,a,b))

n=350
points=[]
for i in range(n+1):
    t0=.25+.5*i/n
    fn0=-.5+2*t0
    for j in range(n+1):
        t1=j/n
        fn1=.5*t1
        e=.5*((2/3)*t0+(1/3)*fn0+(1/3)*t1+(2/3)*fn1)
        if e>.251: continue
        u=rowunfair(t0,t1,1/3,1/6)+rowunfair(fn0,fn1,1/6,1/3)
        points.append((u,e,t0,t1))
points.sort()
pareto=[]
best_e=inf
for p in points:
    if p[1]<best_e-1e-12:
        pareto.append(p)
        best_e=p[1]
hull=[]
for p in pareto:
    while len(hull)>1:
        a,b=hull[-2:]
        cross=(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0])
        if cross<=0: hull.pop()
        else: break
    hull.append(p)
max_gap=(0,None,None,None)
for a,b in zip(hull,hull[1:]):
    for p in pareto:
        if a[0]<p[0]<b[0]:
            interp=a[1]+(b[1]-a[1])*(p[0]-a[0])/(b[0]-a[0])
            if p[1]-interp>max_gap[0]: max_gap=(p[1]-interp,p,a,b)
print('Figure 1 sampled frontier:', {'pareto_points':len(pareto),'hull_vertices':len(hull),'largest_error_above_hull':max_gap})
PY"
